  function updateClock(){const n=new Date();if($('#mainClock')){$('#mainClock').childNodes[0].textContent=localTime(n).slice(0,5);$('#clockSeconds').textContent=':'+String(n.getSeconds()).padStart(2,'0');$('#mainDate').textContent=n.toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'});$('#todayLabel').textContent=n.toLocaleDateString(undefined,{weekday:'long'}).toUpperCase()}renderCities();checkAlarms();updateNextAlarmCard();}
  function switchTab(name){$$('.tab').forEach(b=>{const on=b.dataset.tab===name;b.classList.toggle('active',on);b.setAttribute('aria-selected',String(on))});$$('.tab-panel').forEach(p=>{const on=p.id==='tab-'+name;p.hidden=!on;p.classList.toggle('active',on)});$('#addAlarmBtn').hidden=name!=='alarm';}
