  function daysLabel(days){if(!days.length)return 'Once';if(days.length===7)return 'Every day';if(days.join(',')==='1,2,3,4,5')return 'Weekdays';if(days.join(',')==='0,6')return 'Weekends';return days.slice().sort((a,b)=>a-b).map(d=>DAY_NAMES[d]).join(', ')}
