  function openAlarmDialog(id=null){state.editingId=id;state.clearCustomAudio=false;const a=id?state.alarms.find(x=>x.id===id):null;$('#dialogTitle').textContent=a?'Edit alarm':'New alarm';$('#saveAlarmBtn').textContent=a?'Save changes':'Save alarm';$('#alarmTime').value=a?.time||'07:00';$('#alarmName').value=a?.label||'';setDays(a?.days||[]);$('#alarmSound').value=a?.sound||'sunrise';$('#alarmVolume').value=String(a?.volume??.75);$('#alarmMission').value=MISSIONS[a?.mission]?a.mission:'jacks';$('#customAlarmAudio').value='';$('#audioFileLabel').textContent='Choose an audio file';$('#savedAudioRow').hidden=!a?.customAudio;$('#savedAudioText').textContent=a?.customAudio?'A custom ringtone is saved for this alarm.':'';updateMissionPreview($('#alarmMission').value);$('#alarmDialog').showModal()}
