    let lang='',hasRunSuccessfully=false;const editor=$('#codeEditor'),output=$('#codeOutput'),status=$('#codeRunStatus'),preview=$('#htmlPreviewWrap');
    function choose(next){lang=next;hasRunSuccessfully=false;$('#finishCodeMission').disabled=true;$$('.code-language').forEach(b=>b.classList.toggle('active',b.dataset.language===lang));editor.value=examples[lang];status.textContent=lang.toUpperCase()+' ready';output.textContent='Press Run code to execute your program.';preview.hidden=lang!=='html'}
    $$('.code-language').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.language)));
    $('#resetCodeBtn').addEventListener('click',()=>{if(!lang){feedback('Choose a language first.','bad');return}editor.value=examples[lang];output.textContent='Starter code restored.';status.textContent='Ready'});
    $('#runCodeBtn').addEventListener('click',async()=>{if(!lang){feedback('Choose a programming language first.','bad');return}if(!editor.value.trim()){feedback('Write some code before running it.','bad');return}const btn=$('#runCodeBtn');btn.disabled=true;status.textContent='Running…';output.textContent='Running your code…';preview.hidden=true;try{if(lang==='html'){$('#htmlPreview').srcdoc=editor.value;preview.hidden=false;output.textContent='HTML loaded in the preview below.';status.textContent='Preview ready';hasRunSuccessfully=true;$('#finishCodeMission').disabled=false;return}const res=await fetch('https://emkc.org/api/v2/piston/execute',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({language:lang,version:'*',files:[{content:editor.value}]})});if(!res.ok)throw new Error('Compiler service returned '+res.status);const result=await res.json();const out=[result.compile?.output,result.run?.output,result.compile?.stderr,result.run?.stderr].filter(Boolean).join('\n').trim();output.textContent=out||'(Program finished with no output.)';hasRunSuccessfully=result.run?.code===0&&(!result.compile||result.compile.code===0);status.textContent=hasRunSuccessfully?'Finished successfully':'Finished with errors';$('#finishCodeMission').disabled=!hasRunSuccessfully}catch(err){output.textContent='Could not run the program. Check internet access and try again.\n\nDetails: '+(err.message||'Compiler unavailable');status.textContent='Run failed';feedback('The compiler could not be reached.','bad')}finally{btn.disabled=false}});
    $('#finishCodeMission').disabled=true;$('#finishCodeMission').addEventListener('click',()=>{if(!hasRunSuccessfully){feedback('Run a program successfully before finishing this mission.','bad');return}missionSuccess()});
