  function missionMemory(){const seq=Array.from({length:5},()=>1+Math.floor(Math.random()*9)).join(' ');missionBase(MISSIONS.memory,'Memorize the sequence, then enter it exactly.');$('#missionBody').innerHTML+=`<div class="math-question" id="memorySequence">${seq}</div><button class="btn btn-secondary btn-full" id="hideSequence">Hide sequence</button><label class="field"><span>TYPE THE SEQUENCE</span><input id="memoryAnswer" placeholder="e.g. 2 4 1 8 3"></label><button class="btn btn-primary btn-full" id="checkMemory">Check</button>`;let hidden=false;$('#hideSequence').addEventListener('click',()=>{hidden=true;$('#memorySequence').textContent='Sequence hidden';$('#hideSequence').disabled=true;$('#memoryAnswer').focus()});$('#checkMemory').addEventListener('click',()=>{if(!hidden){feedback('Hide the sequence first, then enter it from memory.','bad');return}$('#memoryAnswer').value.trim().split(/\s+/).join(' ')===seq?missionSuccess():feedback('Sequence does not match. Try again.','bad')})}
