  function missionReaction(){missionBase(MISSIONS.reaction,'Wait for the green signal, then tap it as quickly as possible.');$('#missionBody').innerHTML+=`<button class="btn btn-secondary btn-full" id="reactionButton">Tap to begin</button><p id="reactionStatus" class="mission-body-copy">Do not tap until the button turns green.</p>`;let ready=false,started=false;$('#reactionButton').addEventListener('click',()=>{if(!started){started=true;$('#reactionButton').disabled=true;$('#reactionStatus').textContent='Wait…';state.missionTimer=setTimeout(()=>{state.missionTimer=null;if(!$('#missionDialog').open)return;ready=true;$('#reactionButton').disabled=false;$('#reactionButton').textContent='TAP NOW';$('#reactionButton').style.background='#00e676';$('#reactionStatus').textContent='Go!'},1200+Math.random()*2800);return}if(ready)missionSuccess();else feedback('Wait for the signal before tapping.','bad')})}
  function missionWord(){const words=['PLANET','MORNING','CODING','ENERGY','PUZZLE'],word=words[Math.floor(Math.random()*words.length)],scrambled=(()=>{let v=word;while(v===word)v=word.split('').sort(()=>Math.random()-.5).join('');return v})();missionBase(MISSIONS.word,'Unscramble the letters to find the word.');$('#missionBody').innerHTML+=`<div class="math-question">${scrambled}</div><label class="field"><span>YOUR ANSWER</span><input id="wordAnswer" autocomplete="off"></label><button class="btn btn-primary btn-full" id="checkWord">Check</button>`;$('#checkWord').addEventListener('click',()=>$('#wordAnswer').value.trim().toUpperCase()===word?missionSuccess():feedback('Not that word. Try again.','bad'))}
  function missionObject(){
    const choices=[{label:'bottle',say:'a bottle',className:'bottle'},{label:'cup',say:'a cup',className:'cup'},{label:'book',say:'a book',className:'book'},{label:'cell phone',say:'a phone',className:'cell phone'},{label:'banana',say:'a banana',className:'banana'},{label:'apple',say:'an apple',className:'apple'},{label:'remote',say:'a remote control',className:'remote'},{label:'keyboard',say:'a keyboard',className:'keyboard'},{label:'mouse',say:'a computer mouse',className:'mouse'},{label:'scissors',say:'scissors',className:'scissors'},{label:'toothbrush',say:'a toothbrush',className:'toothbrush'}];const target=choices[Math.floor(Math.random()*choices.length)];missionBase(MISSIONS.object,`Find ${target.say}. Turn on the camera and point it at the object. WakeTask uses an on-device-in-browser object-detection model; it only succeeds when the model sees a matching label confidently. Detection is not perfect, and the camera feed is processed in this page.`);$('#missionBody').innerHTML+=`<div class="mission-big">Find ${target.say}</div><div class="camera-box"><video id="objectVideo" autoplay muted playsinline></video><div id="objectPlaceholder" class="camera-placeholder">Camera is off<br><small>Point it at one object at a time, in good light.</small></div></div><div class="progress"><span id="objectProgress"></span></div><div class="button-row"><button class="btn btn-primary" id="startObjectScan">Start camera check</button></div><p class="field-help" id="objectStatus">The mission will only pass when the requested object is detected.</p>`;
    const video=$('#objectVideo'),status=$('#objectStatus'),progress=$('#objectProgress'),btn=$('#startObjectScan');btn.addEventListener('click',async()=>{btn.disabled=true;status.textContent='Starting camera and loading the object model…';try{await startCamera(video,'environment');await loadScriptOnce('https://cdn.jsdelivr.net/npm/@tensorflow/tfjs@4.22.0/dist/tf.min.js',()=>!!window.tf);await loadScriptOnce('https://cdn.jsdelivr.net/npm/@tensorflow-models/coco-ssd@2.2.3/dist/coco-ssd.min.js',()=>!!window.cocoSsd);state.objectModel=await window.cocoSsd.load({base:'lite_mobilenet_v2'});status.textContent=`Looking for ${target.say}… keep it centered in the frame.`;let hits=0,busy=false;const scan=async()=>{if(!state.stream||!$('#missionDialog').open||!state.objectModel)return;if(video.readyState>=2&&!busy){busy=true;try{const predictions=await state.objectModel.detect(video);const match=predictions.find(p=>p.class===target.className&&p.score>=.55);if(match){hits++;progress.style.width=Math.min(100,hits/3*100)+'%';status.textContent=`${target.label} detected (${Math.round(match.score*100)}% confidence). Hold it steady…`;if(hits>=3){missionSuccess();return}}else{hits=0;progress.style.width='0%';const seen=predictions.filter(p=>p.score>=.45).slice(0,3).map(p=>p.class).join(', ');status.textContent=seen?`I can see: ${seen}. Still looking for ${target.label}.`:`No clear object yet. Move closer, improve lighting, or change the angle.`}}catch(e){status.textContent='Object detection had a problem. Try again with better lighting.'}busy=false}state.missionFrame=requestAnimationFrame(scan)};scan()}catch(err){if(state.stream){state.stream.getTracks().forEach(t=>t.stop());state.stream=null}btn.disabled=false;status.textContent='Camera/model could not start. Allow camera access, use HTTPS, and check your internet connection.';feedback(err.message||'Object detector unavailable.','bad')}})
  }
  // World clock
  $('#addCityBtn').addEventListener('click',()=>{$('#cityAdd').hidden=!$('#cityAdd').hidden});$('#saveCityBtn').addEventListener('click',()=>{const zone=$('#citySelect').value;const name=$('#citySelect').selectedOptions[0].textContent;if(state.cities.some(c=>c.zone===zone)){toast('That city is already on your list');return}state.cities.push({name,zone});saveSaved('waketask-cities',state.cities);$('#cityAdd').hidden=true;renderCities()});
  function renderCities(){
    if(!$('#cityList'))return;
    $('#cityList').innerHTML='';
    state.cities.forEach(c=>{
      const d=new Date(),time=new Intl.DateTimeFormat(undefined,{timeZone:c.zone,hour:'2-digit',minute:'2-digit',hour12:false}).format(d),date=new Intl.DateTimeFormat(undefined,{timeZone:c.zone,weekday:'short',month:'short',day:'numeric'}).format(d);
      const row=document.createElement('div');
      row.className='city-row'+(c.zone==='Asia/Manila'?' city-fixed':' city-swipeable');
      row.setAttribute('role','group');
      row.setAttribute('aria-label',c.name+(c.zone==='Asia/Manila'?' (local city)':' (swipe left to remove)'));
      row.innerHTML=`<div class="city-details"><strong>${escapeHTML(c.name)}</strong><small>${date} · ${isDay(c.zone)?'Daytime':'Nighttime'}</small></div><div class="city-time">${time}<small>${escapeHTML(c.zone.replace('_',' '))}</small></div>`;
      if(c.zone!=='Asia/Manila'){
        let startX=0,startY=0,tracking=false;
        row.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;startX=e.clientX;startY=e.clientY;tracking=true;row.classList.remove('swipe-revealed')});
        row.addEventListener('pointerup',e=>{
          if(!tracking)return;tracking=false;
          const dx=e.clientX-startX,dy=e.clientY-startY;
          if(dx < -65 && Math.abs(dx)>Math.abs(dy)*1.25){
            row.classList.add('swipe-removing');
            row.addEventListener('transitionend',function removeCity(){row.removeEventListener('transitionend',removeCity);state.cities=state.cities.filter(x=>x.zone!==c.zone);saveSaved('waketask-cities',state.cities);renderCities()},{once:true});
          } else if(dx > 45){row.classList.remove('swipe-removing')}
        });
        row.addEventListener('pointercancel',()=>{tracking=false});
        row.addEventListener('keydown',e=>{if((e.key==='Delete'||e.key==='Backspace')&&e.target===row){state.cities=state.cities.filter(x=>x.zone!==c.zone);saveSaved('waketask-cities',state.cities);renderCities()}});
      }
      $('#cityList').append(row);
    });
  }
  function isDay(zone){const h=Number(new Intl.DateTimeFormat('en-US',{timeZone:zone,hour:'numeric',hour12:false}).format(new Date()));return h>=6&&h<18}
  // Timer supports multiple concurrent countdowns.
  function inputTimerSeconds(){const h=clampInt($('#timerHours').value,0,99),m=clampInt($('#timerMinutes').value,0,59),s=clampInt($('#timerSecs').value,0,59);return h*3600+m*60+s}
  function clampInt(v,min,max){return Math.max(min,Math.min(max,Math.floor(Number(v)||0)))}
  function formatDuration(total){total=Math.max(0,Math.floor(total));const h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=total%60;return [h,m,s].map(v=>String(v).padStart(2,'0')).join(':')}
